from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parent / "POED"

FILES = '{\'config.json\': \'{\\n    "name": "POED",\\n    "version": "0.5.0",\\n    "ai": {\\n        "enabled": false,\\n        "provider": "openai",\\n        "model": "gpt-5.6"\\n    },\\n    "security": {\\n        "require_confirmation": true\\n    }\\n}\', \'.gitignore\': \'.venv/\\n.env\\n__pycache__/\\n*.pyc\\ndata/poed.log\\n\', \'.env.example\': \'OPENAI_API_KEY=your_key_here\\n\', \'data/memory.json\': \'{\\n    "user_name": null,\\n    "facts": []\\n}\', \'system.py\': \'import os\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\nimport psutil\\nimport pyautogui\\n\\n\\ndef get_cpu_usage():\\n    return psutil.cpu_percent(interval=0.5)\\n\\n\\ndef get_ram_usage():\\n    memory = psutil.virtual_memory()\\n    return {\\n        "percent": memory.percent,\\n        "used_gb": round(memory.used / 1024**3, 2),\\n        "total_gb": round(memory.total / 1024**3, 2),\\n        "available_gb": round(memory.available / 1024**3, 2),\\n    }\\n\\n\\ndef get_disk_usage():\\n    result = []\\n    for partition in psutil.disk_partitions():\\n        try:\\n            usage = psutil.disk_usage(partition.mountpoint)\\n            result.append({\\n                "drive": partition.mountpoint,\\n                "percent": usage.percent,\\n                "used_gb": round(usage.used / 1024**3, 2),\\n                "total_gb": round(usage.total / 1024**3, 2),\\n            })\\n        except (PermissionError, OSError):\\n            pass\\n    return result\\n\\n\\ndef open_browser():\\n    os.startfile("https://www.google.com")\\n\\n\\ndef open_notepad():\\n    subprocess.Popen(["notepad.exe"])\\n\\n\\ndef open_calculator():\\n    subprocess.Popen(["calc.exe"])\\n\\n\\ndef open_explorer():\\n    subprocess.Popen(["explorer.exe"])\\n\\n\\ndef create_folder(name):\\n    safe_name = Path(name).name.strip()\\n    if not safe_name:\\n        return "Имя папки пустое."\\n\\n    path = Path.home() / "Desktop" / safe_name\\n    path.mkdir(parents=True, exist_ok=True)\\n    return f"Папка создана: {path}"\\n\\n\\ndef take_screenshot():\\n    folder = Path("data") / "screenshots"\\n    folder.mkdir(parents=True, exist_ok=True)\\n    filename = folder / f"screenshot_{int(time.time())}.png"\\n    pyautogui.screenshot().save(filename)\\n    return f"Скриншот сохранён: {filename}"\\n\\n\\ndef get_processes(limit=20):\\n    processes = []\\n    for process in psutil.process_iter(\\n        ["pid", "name", "cpu_percent", "memory_percent"]\\n    ):\\n        try:\\n            info = process.info\\n            processes.append({\\n                "pid": info["pid"],\\n                "name": info["name"],\\n                "cpu": round(info["cpu_percent"] or 0, 1),\\n                "memory": round(info["memory_percent"] or 0, 1),\\n            })\\n        except (psutil.NoSuchProcess, psutil.AccessDenied):\\n            pass\\n\\n    processes.sort(key=lambda x: x["cpu"], reverse=True)\\n    return processes[:limit]\\n\\n\\ndef shutdown_pc():\\n    subprocess.Popen(["shutdown", "/s", "/t", "30"])\\n\\n\\ndef restart_pc():\\n    subprocess.Popen(["shutdown", "/r", "/t", "30"])\\n\\n\\ndef cancel_shutdown():\\n    subprocess.Popen(["shutdown", "/a"])\\n\', \'hardware.py\': \'import shutil\\nimport subprocess\\nimport psutil\\n\\n\\nclass HardwareMonitor:\\n\\n    def get_cpu(self):\\n        freq = psutil.cpu_freq()\\n        return {\\n            "usage": psutil.cpu_percent(interval=0.5),\\n            "cores": psutil.cpu_count(logical=False),\\n            "threads": psutil.cpu_count(logical=True),\\n            "frequency_mhz": round(freq.current, 0) if freq else 0,\\n        }\\n\\n    def get_ram(self):\\n        memory = psutil.virtual_memory()\\n        return {\\n            "usage": memory.percent,\\n            "used_gb": round(memory.used / 1024**3, 2),\\n            "total_gb": round(memory.total / 1024**3, 2),\\n            "available_gb": round(memory.available / 1024**3, 2),\\n        }\\n\\n    def get_disks(self):\\n        result = []\\n        for partition in psutil.disk_partitions():\\n            try:\\n                usage = psutil.disk_usage(partition.mountpoint)\\n                result.append({\\n                    "drive": partition.mountpoint,\\n                    "usage": usage.percent,\\n                    "used_gb": round(usage.used / 1024**3, 2),\\n                    "total_gb": round(usage.total / 1024**3, 2),\\n                })\\n            except (PermissionError, OSError):\\n                pass\\n        return result\\n\\n    def get_gpu(self):\\n        if shutil.which("nvidia-smi") is None:\\n            return {\\n                "available": False,\\n                "message": "NVIDIA GPU не обнаружена или nvidia-smi недоступна.",\\n            }\\n\\n        try:\\n            command = [\\n                "nvidia-smi",\\n                "--query-gpu=name,utilization.gpu,temperature.gpu,"\\n                "memory.used,memory.total,power.draw,clocks.gr,clocks.mem",\\n                "--format=csv,noheader,nounits",\\n            ]\\n\\n            result = subprocess.run(\\n                command,\\n                capture_output=True,\\n                text=True,\\n                timeout=5,\\n            )\\n\\n            if result.returncode != 0 or not result.stdout.strip():\\n                return {\\n                    "available": False,\\n                    "message": "Не удалось получить данные GPU.",\\n                }\\n\\n            values = [v.strip() for v in result.stdout.strip().split(",")]\\n\\n            return {\\n                "available": True,\\n                "name": values[0],\\n                "usage": float(values[1]),\\n                "temperature": float(values[2]),\\n                "memory_used_mb": float(values[3]),\\n                "memory_total_mb": float(values[4]),\\n                "power_w": float(values[5]),\\n                "core_clock_mhz": float(values[6]),\\n                "memory_clock_mhz": float(values[7]),\\n            }\\n\\n        except Exception as error:\\n            return {\\n                "available": False,\\n                "message": f"Ошибка получения GPU: {error}",\\n            }\\n\\n    def get_all(self):\\n        return {\\n            "cpu": self.get_cpu(),\\n            "ram": self.get_ram(),\\n            "gpu": self.get_gpu(),\\n            "disks": self.get_disks(),\\n        }\\n\', \'tools.py\': \'import subprocess\\nimport webbrowser\\n\\nimport system\\nfrom hardware import HardwareMonitor\\n\\n\\nclass POEDTools:\\n\\n    def __init__(self):\\n        self.hardware = HardwareMonitor()\\n\\n    def open_browser(self):\\n        system.open_browser()\\n        return "Браузер открыт."\\n\\n    def open_google(self):\\n        webbrowser.open("https://www.google.com")\\n        return "Google открыт."\\n\\n    def open_youtube(self):\\n        webbrowser.open("https://www.youtube.com")\\n        return "YouTube открыт."\\n\\n    def open_notepad(self):\\n        system.open_notepad()\\n        return "Блокнот открыт."\\n\\n    def open_calculator(self):\\n        system.open_calculator()\\n        return "Калькулятор открыт."\\n\\n    def open_explorer(self):\\n        system.open_explorer()\\n        return "Проводник открыт."\\n\\n    def open_discord(self):\\n        webbrowser.open("https://discord.com/app")\\n        return "Discord открыт."\\n\\n    def open_steam(self):\\n        subprocess.Popen("steam", shell=True)\\n        return "Steam запущен."\\n\\n    def get_cpu(self):\\n        return self.hardware.get_cpu()\\n\\n    def get_ram(self):\\n        return self.hardware.get_ram()\\n\\n    def get_gpu(self):\\n        return self.hardware.get_gpu()\\n\\n    def get_disks(self):\\n        return self.hardware.get_disks()\\n\\n    def hardware_status(self):\\n        return self.hardware.get_all()\\n\\n    def processes(self):\\n        return system.get_processes()\\n\\n    def screenshot(self):\\n        return system.take_screenshot()\\n\\n    def create_folder(self, name):\\n        return system.create_folder(name)\\n\\n    def shutdown(self):\\n        system.shutdown_pc()\\n        return "Выключение запланировано через 30 секунд."\\n\\n    def restart(self):\\n        system.restart_pc()\\n        return "Перезагрузка запланирована через 30 секунд."\\n\\n    def cancel_shutdown(self):\\n        system.cancel_shutdown()\\n        return "Выключение/перезагрузка отменены."\\n\', \'tool_engine.py\': \'from tools import POEDTools\\n\\n\\nclass ToolEngine:\\n\\n    def __init__(self):\\n        self.tools = POEDTools()\\n        self.available_tools = {\\n            "open_browser": self.tools.open_browser,\\n            "open_google": self.tools.open_google,\\n            "open_youtube": self.tools.open_youtube,\\n            "open_notepad": self.tools.open_notepad,\\n            "open_calculator": self.tools.open_calculator,\\n            "open_explorer": self.tools.open_explorer,\\n            "open_discord": self.tools.open_discord,\\n            "open_steam": self.tools.open_steam,\\n            "get_cpu": self.tools.get_cpu,\\n            "get_ram": self.tools.get_ram,\\n            "get_gpu": self.tools.get_gpu,\\n            "get_disks": self.tools.get_disks,\\n            "hardware_status": self.tools.hardware_status,\\n            "processes": self.tools.processes,\\n            "screenshot": self.tools.screenshot,\\n            "create_folder": self.tools.create_folder,\\n            "shutdown": self.tools.shutdown,\\n            "restart": self.tools.restart,\\n            "cancel_shutdown": self.tools.cancel_shutdown,\\n        }\\n        self.dangerous_tools = {"shutdown", "restart"}\\n\\n    def execute(self, tool_name, *args):\\n        if tool_name not in self.available_tools:\\n            return f"Инструмент \\\'{tool_name}\\\' не найден."\\n\\n        try:\\n            return self.available_tools[tool_name](*args)\\n        except Exception as error:\\n            return f"Ошибка инструмента {tool_name}: {error}"\\n\\n    def is_dangerous(self, tool_name):\\n        return tool_name in self.dangerous_tools\\n\\n    def list_tools(self):\\n        return list(self.available_tools.keys())\\n\', \'security.py\': \'class SecurityManager:\\n\\n    def __init__(self):\\n        self.pending_action = None\\n\\n    def requires_confirmation(self, tool_name):\\n        return tool_name in {"shutdown", "restart"}\\n\\n    def request_confirmation(self, tool_name):\\n        self.pending_action = tool_name\\n\\n        if tool_name == "shutdown":\\n            return "⚠️ POED собирается выключить компьютер.\\\\nПодтвердить? Напиши «да» или «нет»."\\n\\n        if tool_name == "restart":\\n            return "⚠️ POED собирается перезагрузить компьютер.\\\\nПодтвердить? Напиши «да» или «нет»."\\n\\n        return "⚠️ Подтвердить действие? Напиши «да» или «нет»."\\n\\n    def confirm(self):\\n        action = self.pending_action\\n        self.pending_action = None\\n        return action\\n\\n    def cancel(self):\\n        self.pending_action = None\\n\', \'logger.py\': \'from pathlib import Path\\nfrom datetime import datetime\\n\\n\\nclass POEDLogger:\\n\\n    def __init__(self):\\n        Path("data").mkdir(parents=True, exist_ok=True)\\n        self.log_file = Path("data/poed.log")\\n\\n    def write(self, message):\\n        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")\\n        with open(self.log_file, "a", encoding="utf-8") as file:\\n            file.write(f"[{timestamp}] {message}\\\\n")\\n\', \'memory.py\': \'import json\\nfrom pathlib import Path\\n\\n\\nclass Memory:\\n\\n    def __init__(self):\\n        self.path = Path("data/memory.json")\\n        self.path.parent.mkdir(parents=True, exist_ok=True)\\n\\n        if not self.path.exists():\\n            self.save({"user_name": None, "facts": []})\\n\\n    def load(self):\\n        try:\\n            return json.loads(self.path.read_text(encoding="utf-8"))\\n        except Exception:\\n            return {"user_name": None, "facts": []}\\n\\n    def save(self, data):\\n        self.path.write_text(\\n            json.dumps(data, ensure_ascii=False, indent=4),\\n            encoding="utf-8",\\n        )\\n\\n    def add_fact(self, fact):\\n        data = self.load()\\n        if fact not in data["facts"]:\\n            data["facts"].append(fact)\\n        self.save(data)\\n\\n    def get(self):\\n        return self.load()\\n\', \'ai_tools.py\': \'AI_TOOLS = [\\n    {\\n        "type": "function",\\n        "name": "get_cpu",\\n        "description": "Получить загрузку, ядра, потоки и частоту процессора.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "get_ram",\\n        "description": "Получить использование оперативной памяти.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "get_gpu",\\n        "description": "Получить данные NVIDIA GPU.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "get_disks",\\n        "description": "Получить информацию о дисках.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "get_processes",\\n        "description": "Получить список процессов Windows.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "open_browser",\\n        "description": "Открыть браузер.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "open_notepad",\\n        "description": "Открыть Блокнот Windows.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "open_discord",\\n        "description": "Открыть Discord.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "open_steam",\\n        "description": "Открыть Steam.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "take_screenshot",\\n        "description": "Сделать скриншот.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {},\\n            "required": [],\\n            "additionalProperties": False,\\n        },\\n    },\\n    {\\n        "type": "function",\\n        "name": "create_folder",\\n        "description": "Создать папку на рабочем столе.",\\n        "strict": True,\\n        "parameters": {\\n            "type": "object",\\n            "properties": {"name": {"type": "string"}},\\n            "required": ["name"],\\n            "additionalProperties": False,\\n        },\\n    },\\n]\\n\', \'dispatcher.py\': \'class ToolDispatcher:\\n\\n    def __init__(self, tool_engine, security):\\n        self.engine = tool_engine\\n        self.security = security\\n\\n    def execute(self, name, arguments=None):\\n        arguments = arguments or {}\\n\\n        if self.security.requires_confirmation(name):\\n            return {\\n                "confirmation_required": True,\\n                "message": self.security.request_confirmation(name),\\n            }\\n\\n        mapping = {\\n            "get_cpu": ("get_cpu", []),\\n            "get_ram": ("get_ram", []),\\n            "get_gpu": ("get_gpu", []),\\n            "get_disks": ("get_disks", []),\\n            "get_processes": ("processes", []),\\n            "open_browser": ("open_browser", []),\\n            "open_notepad": ("open_notepad", []),\\n            "open_discord": ("open_discord", []),\\n            "open_steam": ("open_steam", []),\\n            "take_screenshot": ("screenshot", []),\\n            "create_folder": ("create_folder", [arguments.get("name", "")]),\\n        }\\n\\n        if name not in mapping:\\n            return f"Инструмент {name} не поддерживается."\\n\\n        tool_name, args = mapping[name]\\n        return self.engine.execute(tool_name, *args)\\n\', \'ai_agent.py\': \'import json\\n\\nfrom openai import OpenAI\\n\\nfrom ai_tools import AI_TOOLS\\nfrom dispatcher import ToolDispatcher\\n\\n\\nclass POEDAgent:\\n\\n    def __init__(self, tool_engine, security, model="gpt-5.6"):\\n        self.client = OpenAI()\\n        self.model = model\\n        self.dispatcher = ToolDispatcher(tool_engine, security)\\n\\n        self.instructions = """\\nТы — POED, локальный AI-ассистент Windows.\\n\\nПонимай естественный русский язык.\\nИспользуй инструменты, когда они нужны.\\nНикогда не выдумывай результат инструмента.\\nОпасные действия не выполняй без подтверждения пользователя.\\nНе используй инструменты, которых нет в списке.\\nОтвечай кратко и понятно.\\n"""\\n\\n    def ask(self, message):\\n        response = self.client.responses.create(\\n            model=self.model,\\n            instructions=self.instructions,\\n            input=message,\\n            tools=AI_TOOLS,\\n            tool_choice="auto",\\n        )\\n\\n        for _ in range(10):\\n            calls = [\\n                item for item in response.output\\n                if item.type == "function_call"\\n            ]\\n\\n            if not calls:\\n                return response.output_text\\n\\n            outputs = []\\n\\n            for call in calls:\\n                try:\\n                    arguments = json.loads(call.arguments or "{}")\\n                except json.JSONDecodeError:\\n                    arguments = {}\\n\\n                result = self.dispatcher.execute(call.name, arguments)\\n\\n                if isinstance(result, dict) and result.get("confirmation_required"):\\n                    return result["message"]\\n\\n                outputs.append({\\n                    "type": "function_call_output",\\n                    "call_id": call.call_id,\\n                    "output": json.dumps(result, ensure_ascii=False),\\n                })\\n\\n            response = self.client.responses.create(\\n                model=self.model,\\n                instructions=self.instructions,\\n                previous_response_id=response.id,\\n                input=outputs,\\n                tools=AI_TOOLS,\\n                tool_choice="auto",\\n            )\\n\\n        return "POED остановил цепочку инструментов, чтобы избежать зацикливания."\\n\', \'assistant.py\': \'import json\\nimport os\\n\\nfrom ai_agent import POEDAgent\\nfrom logger import POEDLogger\\nfrom memory import Memory\\nfrom security import SecurityManager\\nfrom tool_engine import ToolEngine\\n\\n\\nclass POEDAssistant:\\n\\n    def __init__(self):\\n        self.tool_engine = ToolEngine()\\n        self.security = SecurityManager()\\n        self.logger = POEDLogger()\\n        self.memory = Memory()\\n\\n        self.ai_enabled = self._is_ai_enabled()\\n        self.ai_agent = None\\n\\n        if self.ai_enabled and os.getenv("OPENAI_API_KEY"):\\n            try:\\n                with open("config.json", "r", encoding="utf-8") as file:\\n                    config = json.load(file)\\n                model = config.get("ai", {}).get("model", "gpt-5.6")\\n\\n                self.ai_agent = POEDAgent(\\n                    self.tool_engine,\\n                    self.security,\\n                    model=model,\\n                )\\n            except Exception as error:\\n                self.ai_enabled = False\\n                self.logger.write(f"AI INIT ERROR: {error}")\\n        else:\\n            self.ai_enabled = False\\n\\n    def _is_ai_enabled(self):\\n        try:\\n            with open("config.json", "r", encoding="utf-8") as file:\\n                config = json.load(file)\\n            return bool(config.get("ai", {}).get("enabled", False))\\n        except Exception:\\n            return False\\n\\n    def respond(self, text):\\n        command = text.lower().strip()\\n        self.logger.write(f"USER: {text}")\\n\\n        if not command:\\n            return "Напиши команду."\\n\\n        if self.security.pending_action:\\n            if command in {"да", "подтверждаю", "подтвердить", "yes", "y"}:\\n                action = self.security.confirm()\\n                result = self.tool_engine.execute(action)\\n                self.logger.write(f"CONFIRMED: {action}")\\n                return result\\n\\n            if command in {"нет", "отмена", "отменить", "no", "n"}:\\n                self.security.cancel()\\n                return "Действие отменено."\\n\\n            return "Мне нужно подтверждение. Напиши «да» или «нет»."\\n\\n        if command.startswith("запомни "):\\n            fact = text[8:].strip()\\n            if fact:\\n                self.memory.add_fact(fact)\\n                return "Запомнил."\\n\\n        if command in {"что ты помнишь", "что ты обо мне помнишь"}:\\n            facts = self.memory.get().get("facts", [])\\n            return (\\n                "Я пока ничего не запомнил."\\n                if not facts\\n                else "Я помню:\\\\n- " + "\\\\n- ".join(facts)\\n            )\\n\\n        if command in {"помощь", "help", "что ты умеешь"}:\\n            return self.help()\\n\\n        if "характеристики железа" in command or "комплектующие" in command:\\n            return self.tool_engine.execute("hardware_status")\\n\\n        if "видеокарт" in command or "gpu" in command:\\n            return self.tool_engine.execute("get_gpu")\\n\\n        if "процессор" in command or command == "cpu":\\n            return self.tool_engine.execute("get_cpu")\\n\\n        if "оператив" in command or command == "ram":\\n            return self.tool_engine.execute("get_ram")\\n\\n        if "диск" in command or "накопител" in command:\\n            return self.tool_engine.execute("get_disks")\\n\\n        if "процесс" in command:\\n            return self.tool_engine.execute("processes")\\n\\n        if "скриншот" in command:\\n            return self.tool_engine.execute("screenshot")\\n\\n        if "открой браузер" in command:\\n            return self.tool_engine.execute("open_browser")\\n\\n        if "открой google" in command or "открой гугл" in command:\\n            return self.tool_engine.execute("open_google")\\n\\n        if "открой youtube" in command or "открой ютуб" in command:\\n            return self.tool_engine.execute("open_youtube")\\n\\n        if "открой блокнот" in command:\\n            return self.tool_engine.execute("open_notepad")\\n\\n        if "открой калькулятор" in command:\\n            return self.tool_engine.execute("open_calculator")\\n\\n        if "открой проводник" in command:\\n            return self.tool_engine.execute("open_explorer")\\n\\n        if "открой discord" in command:\\n            return self.tool_engine.execute("open_discord")\\n\\n        if "открой steam" in command:\\n            return self.tool_engine.execute("open_steam")\\n\\n        if "отмени выключение" in command or "отмена выключения" in command:\\n            return self.tool_engine.execute("cancel_shutdown")\\n\\n        if "выключи компьютер" in command or "выключи пк" in command:\\n            return self.security.request_confirmation("shutdown")\\n\\n        if "перезагрузи компьютер" in command or "перезагрузи пк" in command:\\n            return self.security.request_confirmation("restart")\\n\\n        if self.ai_enabled and self.ai_agent:\\n            try:\\n                return self.ai_agent.ask(text)\\n            except Exception as error:\\n                self.logger.write(f"AI ERROR: {error}")\\n                return f"Ошибка AI: {error}"\\n\\n        return "Я пока не понял команду. Напиши «помощь». AI сейчас выключен."\\n\\n    def help(self):\\n        return """\\nPOED v0.5\\n\\nПК:\\n• показать процессор\\n• показать видеокарту\\n• показать оперативную память\\n• показать диски\\n• показать характеристики железа\\n• показать процессы\\n• сделать скриншот\\n\\nПрограммы:\\n• открыть браузер\\n• открыть Google\\n• открыть YouTube\\n• открыть Блокнот\\n• открыть Калькулятор\\n• открыть Проводник\\n• открыть Discord\\n• открыть Steam\\n\\nСистема:\\n• выключить компьютер\\n• перезагрузить компьютер\\n• отменить выключение\\n\\nПамять:\\n• «запомни ...»\\n• «что ты помнишь»\\n\\nОпасные действия требуют подтверждения.\\n""".strip()\\n\', \'main.py\': \'import threading\\nimport tkinter as tk\\nfrom tkinter import scrolledtext\\n\\nfrom assistant import POEDAssistant\\n\\n\\nclass POEDWindow:\\n\\n    def __init__(self):\\n        self.assistant = POEDAssistant()\\n\\n        self.root = tk.Tk()\\n        self.root.title("POED AI")\\n        self.root.geometry("900x700")\\n        self.root.minsize(650, 500)\\n\\n        self.create_interface()\\n\\n        self.add_message(\\n            "POED",\\n            "Привет! Я POED.\\\\n\\\\n"\\n            "Локальное ядро запущено.\\\\n"\\n            "Напиши «помощь», чтобы увидеть возможности."\\n        )\\n\\n    def create_interface(self):\\n        header = tk.Frame(self.root)\\n        header.pack(fill="x", padx=15, pady=15)\\n\\n        tk.Label(\\n            header,\\n            text="POED",\\n            font=("Segoe UI", 26, "bold"),\\n        ).pack(side="left")\\n\\n        tk.Label(\\n            header,\\n            text="● Online",\\n            font=("Segoe UI", 10),\\n        ).pack(side="left", padx=15, pady=10)\\n\\n        self.chat = scrolledtext.ScrolledText(\\n            self.root,\\n            wrap=tk.WORD,\\n            font=("Segoe UI", 11),\\n            state="disabled",\\n        )\\n        self.chat.pack(fill="both", expand=True, padx=15, pady=(0, 10))\\n\\n        bottom = tk.Frame(self.root)\\n        bottom.pack(fill="x", padx=15, pady=(0, 15))\\n\\n        self.entry = tk.Entry(bottom, font=("Segoe UI", 12))\\n        self.entry.pack(side="left", fill="x", expand=True, ipady=10)\\n        self.entry.bind("<Return>", self.send_command)\\n\\n        tk.Button(\\n            bottom,\\n            text="Отправить",\\n            command=self.send_command,\\n            font=("Segoe UI", 11),\\n        ).pack(side="right", padx=(10, 0), ipady=6)\\n\\n        self.entry.focus()\\n\\n    def add_message(self, sender, message):\\n        self.chat.config(state="normal")\\n        self.chat.insert(tk.END, f"{sender}\\\\n{message}\\\\n\\\\n")\\n        self.chat.config(state="disabled")\\n        self.chat.see(tk.END)\\n\\n    def send_command(self, event=None):\\n        text = self.entry.get().strip()\\n        if not text:\\n            return\\n\\n        self.entry.delete(0, tk.END)\\n        self.add_message("Ты", text)\\n\\n        threading.Thread(\\n            target=self.process_command,\\n            args=(text,),\\n            daemon=True,\\n        ).start()\\n\\n    def process_command(self, text):\\n        try:\\n            response = self.assistant.respond(text)\\n        except Exception as error:\\n            response = f"Ошибка выполнения:\\\\n\\\\n{error}"\\n\\n        self.root.after(\\n            0,\\n            lambda: self.add_message("POED", str(response)),\\n        )\\n\\n    def run(self):\\n        self.root.mainloop()\\n\\n\\nif __name__ == "__main__":\\n    POEDWindow().run()\\n\', \'run_poed.bat\': \'@echo off\\ncd /d "%~dp0"\\n\\nif not exist ".venv\\\\Scripts\\\\python.exe" (\\n    echo POED is not installed.\\n    echo Run setup_poed.py first.\\n    pause\\n    exit /b 1\\n)\\n\\n".venv\\\\Scripts\\\\python.exe" main.py\\npause\\n\', \'enable_ai.bat\': \'@echo off\\ncd /d "%~dp0"\\n\\npowershell -NoProfile -ExecutionPolicy Bypass -Command "$p=\\\'config.json\\\'; $j=Get-Content $p -Raw | ConvertFrom-Json; $j.ai.enabled=$true; $j | ConvertTo-Json -Depth 10 | Set-Content $p -Encoding UTF8"\\n\\necho AI enabled.\\npause\\n\', \'disable_ai.bat\': \'@echo off\\ncd /d "%~dp0"\\n\\npowershell -NoProfile -ExecutionPolicy Bypass -Command "$p=\\\'config.json\\\'; $j=Get-Content $p -Raw | ConvertFrom-Json; $j.ai.enabled=$false; $j | ConvertTo-Json -Depth 10 | Set-Content $p -Encoding UTF8"\\n\\necho AI disabled.\\npause\\n\', \'README.md\': \'# POED\\n\\nЛокальный AI-ассистент для Windows.\\n\\n## Установка\\n\\nЗапусти `setup_poed.py`.\\n\\nОн создаёт папку `POED`, виртуальное окружение `.venv`, библиотеки и стартовый код.\\n\\n## Запуск\\n\\nЗапусти `run_poed.bat`.\\n\\nAI выключен по умолчанию. Локальные функции ПК работают без API-ключа.\\n\\nНе отправляй API-ключ в чат.\\n\'}'


def write_file(relative, content):
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)

    if path.exists():
        print(f"[SKIP] {relative}")
        return

    path.write_text(content, encoding="utf-8")
    print(f"[CREATE] {relative}")


def run(command):
    print(">", " ".join(map(str, command)))
    subprocess.check_call(command)


def main():
    print("=" * 60)
    print("POED PROJECT INSTALLER")
    print("=" * 60)

    ROOT.mkdir(parents=True, exist_ok=True)

    for relative, content in FILES.items():
        write_file(relative, content)

    venv = ROOT / ".venv"
    python = venv / "Scripts" / "python.exe"

    if not python.exists():
        print("\n[1/3] Creating virtual environment...")
        run([sys.executable, "-m", "venv", str(venv)])
    else:
        print("\n[1/3] Virtual environment already exists.")

    print("\n[2/3] Updating pip...")
    run([str(python), "-m", "pip", "install", "--upgrade", "pip"])

    print("\n[3/3] Installing libraries...")
    run([
        str(python), "-m", "pip", "install",
        "psutil",
        "pyautogui",
        "pillow",
        "openai",
        "python-dotenv",
    ])

    (ROOT / "data" / "screenshots").mkdir(parents=True, exist_ok=True)

    print("\n" + "=" * 60)
    print("POED READY")
    print("=" * 60)
    print(f"\nFolder: {ROOT}")
    print("\nStart: run_poed.bat")
    print("\nAI is OFF by default.")
    print("Existing files were not overwritten.")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nCancelled.")
    except Exception as error:
        print("\nINSTALLATION ERROR:")
        print(error)
        input("\nPress Enter to close...")
